/**
 * 当前时刻达到（等于或晚于）有效期即视为到期；只影响可用性判定与查询标识，不改写状态。
 */
private boolean isExpired(BatchRepository.BatchRow row, Instant now) {
    return !now.isBefore(Instant.parse(row.expiresAt()));
}

